package com.northstarbank.console.web;import com.northstarbank.console.domain.NotificationRepository;import com.northstarbank.console.security.AuthorizationService;import org.springframework.web.bind.annotation.*;
@ControllerAdvice public class GlobalModel{private static final java.util.Random ASSET_RANDOM=new java.util.Random(); // Non-cryptographic: java.util.Random is used only for a static-asset cache-busting suffix.
private static final String ASSET_VERSION=Integer.toUnsignedString(ASSET_RANDOM.nextInt(),36);private final AuthorizationService auth;private final NotificationRepository notes;public GlobalModel(AuthorizationService a,NotificationRepository n){auth=a;notes=n;}@ModelAttribute void global(org.springframework.ui.Model m){m.addAttribute("assetVersion",ASSET_VERSION);var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(a!=null&&a.isAuthenticated()&&a.getPrincipal() instanceof com.northstarbank.console.security.SessionUser u){m.addAttribute("currentUser",u);m.addAttribute("notifications",notes.findTop10ByRecipientAndReadFalseOrderByCreatedAtDesc(u.employeeId()));}}}
